//! The earnings watchlist (`data/watchlist.tsv`, generated by
//! `scripts/build-watchlist.mjs`) and the EDGAR polling window.

use std::sync::OnceLock;

use chrono::{DateTime, Datelike, NaiveTime, Utc, Weekday};

use crate::clock::et;

const DATA: &str = include_str!("../../data/watchlist.tsv");

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Filer {
    /// Files 8-K/10-Q/10-K: polled and written automatically.
    Domestic,
    /// Files 6-K/20-F (no Item 2.02): calendar only.
    Foreign,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tier {
    /// Earnings write-ups: the S&P 100 and every company at or above $100B
    /// in the market-cap snapshot.
    Full,
    /// Calendar only: an 8-K Item 2.02 marks the date reported, no write-up.
    Calendar,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WatchEntry {
    /// Display form, e.g. `BRK.B`.
    pub ticker: &'static str,
    pub cik: u64,
    pub filer: Filer,
    pub name: &'static str,
    /// The company's own web domains; subdomains match. Empty for some
    /// calendar-tier rows (only write-up companies are checked against
    /// company announcements).
    pub domains: Vec<&'static str>,
    /// EDGAR's conformed filer name (for the wrong-CIK guard).
    pub sec: &'static str,
    pub tier: Tier,
}

fn data_lines() -> impl Iterator<Item = &'static str> {
    DATA.lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
}

fn parse(line: &'static str) -> Option<WatchEntry> {
    let mut cols = line.split('\t').map(str::trim);
    let ticker = cols.next()?;
    let cik = cols.next()?.parse().ok()?;
    let filer = match cols.next()? {
        "domestic" => Filer::Domestic,
        "foreign" => Filer::Foreign,
        _ => return None,
    };
    let name = cols.next()?;
    let domains = cols
        .next()
        .unwrap_or("")
        .split(',')
        .map(str::trim)
        .filter(|d| !d.is_empty())
        .collect();
    let sec = cols.next().filter(|s| !s.is_empty())?;
    let tier = match cols.next()? {
        "full" => Tier::Full,
        "calendar" => Tier::Calendar,
        _ => return None,
    };
    Some(WatchEntry {
        ticker,
        cik,
        filer,
        name,
        domains,
        sec,
        tier,
    })
}

/// The parsed file, once per isolate (about 560 rows).
fn entries() -> &'static [WatchEntry] {
    static ALL: OnceLock<Vec<WatchEntry>> = OnceLock::new();
    ALL.get_or_init(|| {
        data_lines()
            .map(|l| parse(l).unwrap_or_else(|| panic!("bad watchlist.tsv row: {l:?}")))
            .collect()
    })
}

/// Every watchlist entry, in file order.
pub fn watchlist() -> Vec<WatchEntry> {
    entries().to_vec()
}

pub fn find(ticker: &str) -> Option<WatchEntry> {
    entries().iter().find(|e| e.ticker == ticker).cloned()
}

pub fn by_cik(cik: u64) -> Option<WatchEntry> {
    entries().iter().find(|e| e.cik == cik).cloned()
}

/// EDGAR's zero-padded 10-digit CIK.
pub fn cik10(cik: u64) -> String {
    format!("{cik:010}")
}

/// Weekdays, 06:00 <= ET < 22:00: when EDGAR is polled and earnings jobs run.
pub fn in_window(now: DateTime<Utc>) -> bool {
    let local = et(now);
    if matches!(local.weekday(), Weekday::Sat | Weekday::Sun) {
        return false;
    }
    let t = local.time();
    t >= NaiveTime::from_hms_opt(6, 0, 0).unwrap() && t < NaiveTime::from_hms_opt(22, 0, 0).unwrap()
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;
    use std::collections::HashSet;

    fn utc(s: &str) -> DateTime<Utc> {
        s.parse().unwrap()
    }

    #[test]
    fn watchlist_shape() {
        let w = watchlist();
        // S&P 500 ∪ Nasdaq-100, one row per CIK, plus the hand-picked
        // foreign companies; the calendar's Yahoo read stays at 12 batches.
        // The floor only catches a truncated file; an index rebalance may
        // drop a dozen names.
        assert!((520..=600).contains(&w.len()), "{}", w.len());
        assert!(
            w.len().div_ceil(crate::yahoo::QUOTE_BATCH) <= 12,
            "{}",
            w.len()
        );
        let tickers: HashSet<_> = w.iter().map(|e| e.ticker).collect();
        let ciks: HashSet<_> = w.iter().map(|e| e.cik).collect();
        assert_eq!(tickers.len(), w.len(), "duplicate ticker");
        assert_eq!(ciks.len(), w.len(), "duplicate CIK");
        assert!(w.iter().all(|e| !e.name.is_empty() && !e.sec.is_empty()));
        assert_eq!(find("AAPL").unwrap().cik, 320193);
        assert_eq!(find("BRK.B").unwrap().name, "Berkshire Hathaway");
        assert_eq!(find("TM").unwrap().filer, Filer::Foreign);
        assert_eq!(by_cik(789019).unwrap().ticker, "MSFT");
        // One share class per company.
        assert!(find("GOOGL").is_some() && find("GOOG").is_none());
        assert!(find("FOXA").is_some() && find("FOX").is_none());
    }

    #[test]
    fn tiers() {
        let w = watchlist();
        let full: Vec<_> = w.iter().filter(|e| e.tier == Tier::Full).collect();
        // The S&P 100 (102 rows) plus the $100B line.
        assert!((102..=200).contains(&full.len()), "{}", full.len());
        // Write-up companies are checked against their own announcements.
        assert!(
            full.iter().all(|e| !e.domains.is_empty()),
            "full row without domains"
        );
        // A foreign (6-K) filer has no Item 2.02 to write from.
        assert!(w
            .iter()
            .filter(|e| e.filer == Filer::Foreign)
            .all(|e| e.tier == Tier::Calendar));
        for t in ["AAPL", "BRK.B", "XOM", "BNY"] {
            assert_eq!(find(t).unwrap().tier, Tier::Full, "{t}");
        }
        // Rick's hand-picked foreign companies: calendar only, even when
        // they file 8-Ks (Teva, Enbridge).
        for t in ["ENB", "SONY", "RACE", "RYAAY", "TEVA", "TSM", "ASML"] {
            assert_eq!(find(t).unwrap().tier, Tier::Calendar, "{t}");
        }
        assert_eq!(find("TEVA").unwrap().filer, Filer::Domestic);
        assert_eq!(find("A").unwrap().tier, Tier::Calendar);
    }

    /// Large Chinese companies listed in the US (Rick, 2026-11-06, "Yes,
    /// ~30 of them"): calendar only, and all but Yum China (a Delaware
    /// company filing 10-Q/8-K) are 20-F/6-K filers.
    pub(crate) const CHINA: [&str; 30] = [
        "BABA", "PDD", "JD", "BIDU", "NTES", "TCOM", "TME", "BILI", "NIO", "XPEV", "LI", "FUTU",
        "TIGR", "BZ", "YMM", "VIPS", "ZTO", "HTHT", "BEKE", "TAL", "EDU", "YUMC", "QFIN", "LU",
        "HSAI", "WB", "IQ", "GDS", "MNSO", "ATAT",
    ];

    #[test]
    fn chinese_companies_are_calendar_only() {
        for t in CHINA {
            let e = find(t).unwrap_or_else(|| panic!("{t} missing"));
            assert_eq!(e.tier, Tier::Calendar, "{t}");
            let filer = if t == "YUMC" {
                Filer::Domestic
            } else {
                Filer::Foreign
            };
            assert_eq!(e.filer, filer, "{t}");
        }
        // Not US-exchange listed (Luckin trades OTC) or no longer listed
        // (Zeekr was taken private).
        assert!(find("LKNCY").is_none() && find("ZK").is_none());
    }

    #[test]
    fn ciks_match_sec_company_tickers() {
        // Checked against https://www.sec.gov/files/company_tickers.json on
        // 2026-10-29: BNY trades as BNY (was BK); XOM's filer is the new
        // holding company.
        assert!(find("BK").is_none());
        assert_eq!(find("BNY").unwrap().cik, 1390777);
        let xom = find("XOM").unwrap();
        assert_eq!((xom.cik, xom.name), (2115436, "ExxonMobil"));
        assert!(by_cik(34088).is_none());
    }

    #[test]
    fn every_row_parses() {
        assert_eq!(data_lines().count(), watchlist().len());
    }

    #[test]
    fn cik_padding() {
        assert_eq!(cik10(320193), "0000320193");
        assert_eq!(cik10(1800), "0000001800");
    }

    #[test]
    fn window_edges_and_dst() {
        // Fri 2026-10-30 is EDT (UTC-4).
        assert!(!in_window(utc("2026-10-30T09:59:59Z"))); // 05:59:59 ET
        assert!(in_window(utc("2026-10-30T10:00:00Z"))); // 06:00 ET
        assert!(in_window(utc("2026-10-31T01:59:59Z"))); // Fri 21:59:59 ET
        assert!(!in_window(utc("2026-10-31T02:00:00Z"))); // Fri 22:00 ET

        // Mon 2026-11-02 is EST (UTC-5).
        assert!(!in_window(utc("2026-11-02T10:30:00Z"))); // 05:30 ET
        assert!(in_window(utc("2026-11-02T11:00:00Z"))); // 06:00 ET
                                                         // Saturday.
        assert!(!in_window(utc("2026-10-31T15:00:00Z")));
    }
}
